import {createServer} from 'node:http';
import {readFile,writeFile,mkdir} from 'node:fs/promises';
import {resolve} from 'node:path';
import {chromium} from '@playwright/test';
import assert from 'node:assert/strict';
const output=resolve(process.env.RESPONSE_CONTROL_OUT);await mkdir(output,{recursive:true});
const png=await readFile('tests/fixtures/art-water-0.png');
let reads=0, held;
const server=createServer((req,res)=>{
 if(req.url.startsWith('/api/')){
  reads++;res.writeHead(200,{'content-type':'image/png','cache-control':'no-store'});
  if(reads===1)res.end(png);else{res.flushHeaders();res.write(png.subarray(0,8));held=res;}
 }else res.end(`<script>window.read=async()=>{window.controller=new AbortController();try{const r=await fetch('/api/projects/owned/recipes/recipe/processed?frame=0',{signal:controller.signal});const b=await r.arrayBuffer();const d=await crypto.subtle.digest('SHA-256',b);const i=new Image();i.src=URL.createObjectURL(new Blob([b],{type:'image/png'}));await i.decode();i.id='saved';i.dataset.sha=[...new Uint8Array(d)].map(x=>x.toString(16).padStart(2,'0')).join('');document.getElementById('saved')?.remove();document.body.append(i);}catch(e){window.lastError=e.name;}};</script>`);
});await new Promise(r=>server.listen(0,'127.0.0.1',r));const origin='http://127.0.0.1:'+server.address().port;
const browser=await chromium.launch(),page=await browser.newPage(),bodies=new Map(),network=[];let navigations=0;page.on('framenavigated',()=>navigations++);page.on('requestfailed',r=>network.push({event:'failed',url:r.url(),failure:r.failure()}));
page.on('response',r=>{if(r.url().includes('/api/')){const body=r.body();void body.catch(()=>undefined);bodies.set(r.url(),body);network.push({event:'response',url:r.url(),status:r.status()});}});
try{
 await page.goto(origin);await page.evaluate(()=>window.read());const url=origin+'/api/projects/owned/recipes/recipe/processed?frame=0';assert.deepEqual(await page.locator('#saved').evaluate(i=>[i.naturalWidth,i.naturalHeight]),[96,144]);const first=await bodies.get(url);
 const response=page.waitForResponse(url),failed=page.waitForEvent('requestfailed');await page.evaluate(()=>{window.pending=window.read()});await response;assert(held);await page.evaluate(()=>window.controller.abort());await failed;await page.evaluate(()=>window.pending);
 let error;try{await bodies.get(url);}catch(e){error=e.message;}assert(error&&error.includes('No data found for resource'));assert.equal(navigations,1);assert.deepEqual(await page.locator('#saved').evaluate(i=>[i.naturalWidth,i.naturalHeight]),[96,144]);assert.equal(reads,2);
 await writeFile(resolve(output,'evidence.json'),JSON.stringify({classification:'OLD_URL_MAP_COUNTEREXAMPLE_CAPTURED_NOT_PASS',source:'39daa13188eb401c2048a24e0606c1a91192e04a',navigations,reads,retainedFirstImage:true,firstBodyBytes:first.length,error,network},null,2)+'\n');console.log('Real Chromium abort reproduces original protocol error without navigation; sameURL promise overwrote displayed successful body');
}finally{held?.destroy();await browser.close();server.closeAllConnections();await new Promise(r=>server.close(r));}
